SELECT * FROM byai_group_chat_task
WHERE group_session_id = #{groupSessionId}
ORDER BY create_time DESC, task_session_id DESC

SELECT s.* FROM byai_session s WHERE s.parent_session_id = #{groupId} AND s.creator_id = #{userId}
  AND s.object_id = #{agentId} AND 
ORDER BY s.create_time, s.session_id LIMIT 1

SELECT m.* FROM byai_message m WHERE NOT EXISTS (
    SELECT 1 FROM () direct
    WHERE direct.task_session_id = m.session_id AND (direct.initiator_user_id != #{actorId} OR NOT EXISTS (
        SELECT 1 FROM byai_session g JOIN byai_session_member member ON member.session_id = g.session_id
        WHERE g.session_id = direct.group_session_id AND g.session_type = 'hs_as'
          AND COALESCE(g.state, 'ACTIVE') != 'GROUP_DISSOLVED' AND member.mem_obj_type = 'USER'
          AND member.mem_obj_id = #{actorId}
    ))
)
AND m.creator_id = #{qo.creatorId}
ORDER BY m.create_time DESC, m.message_id DESC

mapper.update:
UPDATE byai_group_chat_task SET turn_status = #{turnStatus}, update_time = #{now}
WHERE task_session_id = #{taskSessionId} AND status = 'ACTIVE'
  AND turn_status = 'RUNNING' AND current_turn_trace_id = #{traceId}

UPDATE byai_group_chat_task SET turn_status = 'RUNNING', current_turn_id = #{turnId},
    current_turn_trace_id = NULL, update_time = #{now}
WHERE task_session_id = #{taskSessionId} AND status = 'ACTIVE'

UPDATE byai_group_chat_task SET current_turn_trace_id = #{traceId}, update_time = #{now}
WHERE task_session_id = #{taskSessionId} AND status = 'ACTIVE' AND turn_status = 'RUNNING'
  AND current_turn_id = #{turnId}
  AND (current_turn_trace_id IS NULL OR current_turn_trace_id = #{traceId})

UPDATE byai_group_chat_task SET turn_status = 'FAILED', update_time = #{now}
WHERE task_session_id = #{taskSessionId} AND status = 'ACTIVE' AND turn_status = 'RUNNING'
  AND current_turn_id = #{turnId}

