SELECT task_session_id, current_turn_id, current_turn_trace_id FROM byai_group_chat_task
WHERE status = 'ACTIVE' AND turn_status = 'RUNNING'
  AND current_turn_id IS NOT NULL AND current_turn_trace_id IS NOT NULL
  AND task_session_id > #{afterId}
ORDER BY task_session_id LIMIT #{limit}
